public static SysOperationController construct(Args _args)
{
    SysOperationController controller = new NWV_TestInventoryValueReportStorage(classstr(InventValueProcessService),
                                                methodstr(InventValueProcessService, process),
                                                SysOperationExecutionMode::Synchronous);
    controller.parmArgs(_args);

    controller.batchInfo().parmRetriesOnFailure(0);

    return controller;
}

